17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
23	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
24	    @Mapping(target = "householdId", expression = "java(formatHouseholdId(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
28	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
32	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
33	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /** Format an owner's name as 'LastName, FirstName' from the stored names. */
38	    default String formatDisplayName(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        return owner.getLastName() + ", " + owner.getFirstName();
43	    }
44	
45	    /**
46	     * Format an owner's initials as the upper-cased first letters of firstName and lastName,
47	     * dot-separated with a trailing dot (e.g. 'J.S.').
48	     */
49	    default String formatInitials(Owner owner) {
50	        if (owner == null) {
51	            return null;
52	        }
53	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
54	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
55	    }
56	
57	    /**
58	     * Compute the owner's household id, the stable identifier shared by all owners in the same
59	     * household, i.e. with the same last name and postcode (see {@link Owner#householdId(String, String)}).
60	     */
61	    default String formatHouseholdId(Owner owner) {
62	        if (owner == null) {
63	            return null;
64	        }
65	        return Owner.householdId(owner.getLastName(), owner.getPostcode());
66	    }
67	
68	    /**
69	     * Compute the owner's membership number, the stable identifier derived from the owner's
70	     * customer code and registration date (see {@link Owner#membershipNumber(String, java.time.LocalDate)}).
71	     */
72	    default String formatMembershipNumber(Owner owner) {
73	        if (owner == null) {
74	            return null;
75	        }
76	        return Owner.membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate());
77	    }
78	
79	    /**
80	     * Compute the owner's membership level, the derived numeric level based on the owner's namesake
81	     * count and whether an email is present
82	     * (see {@link Owner#membershipLevel(Integer, String)}).
83	     */
84	    default Integer formatMembershipLevel(Owner owner) {
85	        if (owner == null) {
86	            return null;
87	        }
88	        return Owner.membershipLevel(owner.getNamesakeCount(), owner.getEmail());
89	    }
90	
91	    /**
92	     * Compute the owner's locality, the canonical region taken from the {@code REGION} segment of the
93	     * owner's customer code (see {@link Owner#locality(String)}).
94	     */
95	    default String formatLocality(Owner owner) {
96	        if (owner == null) {
97	            return null;
98	        }
99	        return Owner.locality(owner.getCustomerCode());
100	    }
101	
